 public MainForm(){Text="CyberPW Assistant 2.0 (BETA)";StartPosition=FormStartPosition.CenterScreen;MinimumSize=new Size(960,680);Size=new Size(1280,820);BackColor=Theme.Ink;ForeColor=Theme.Text;Font=new Font("Segoe UI",9);AutoScaleMode=AutoScaleMode.Dpi;Icon=LoadIcon();var root=new TableLayoutPanel{Dock=DockStyle.Fill,Margin=Padding.Empty,Padding=new Padding(3),ColumnCount=2,RowCount=1,BackColor=Theme.Gold};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,230));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);nav=new GradientPanel{Dock=DockStyle.Fill,Margin=Padding.Empty,Edges=FrameEdges.Right,BorderThickness=3,AutoScroll=true};var work=new TableLayoutPanel{Dock=DockStyle.Fill,Margin=Padding.Empty,Padding=Padding.Empty,RowCount=3,ColumnCount=1,BackColor=Theme.Ink};work.RowStyles.Add(new RowStyle(SizeType.Absolute,62));work.RowStyles.Add(new RowStyle(SizeType.Percent,100));work.RowStyles.Add(new RowStyle(SizeType.Absolute,44));root.Controls.Add(nav,0,0);root.Controls.Add(work,1,0);var header=new GradientPanel{Dock=DockStyle.Fill,Margin=Padding.Empty,Edges=FrameEdges.Bottom,BorderThickness=3};var ready=Theme.Label("●  CYBERPW · ІНСТРУМЕНТИ ГОТОВІ",10,Theme.Text,FontStyle.Bold);ready.Location=new Point(24,21);header.Controls.Add(ready);titleCount=Theme.Label("Титули: 0 / 260",10,Theme.GoldSoft,FontStyle.Bold);titleCount.AutoSize=false;titleCount.Size=new Size(220,26);titleCount.TextAlign=ContentAlignment.MiddleRight;titleCount.Anchor=AnchorStyles.Top|AnchorStyles.Right;header.Controls.Add(titleCount);updateButton=Theme.Button("↻ ОНОВЛЕННЯ");updateButton.SetBounds(0,14,140,34);updateButton.Click+=(s,e)=>CheckUpdates(true);header.Controls.Add(updateButton);header.Resize+=(s,e)=>{titleCount.Location=new Point(header.ClientSize.Width-titleCount.Width-24,18);updateButton.Location=new Point(Math.Max(310,header.ClientSize.Width-titleCount.Width-updateButton.Width-42),14);};content=new Panel{Dock=DockStyle.Fill,Margin=Padding.Empty,Padding=Padding.Empty,BackColor=Theme.Ink};var footer=BuildFooter();work.Controls.Add(header,0,0);work.Controls.Add(content,0,1);work.Controls.Add(footer,0,2);BuildNav();Register("ГОЛОВНА",new DashboardPage(ShowPage),new Size(1030,650));Register("TITULHELPER",new TitlesPage(),new Size(1080,680));Register("MULTILAUNCHER",new MultiLauncherPage(),new Size(850,630));Register("МАКРОСИ",new MacroStudioPage(),new Size(930,650));Register("РЕСИ",new ResourcesPage(),new Size(1030,650));Register("СИМУЛЯТОР",new SimulatorPage(),new Size(900,650));Register("ЗАТОЧКА",new RefinementSimulatorPage(),new Size(1030,650));Register("ВІКТОРИНА КХ",new GuildQuizPage(),new Size(1030,650));Register("ВІКТОРИНА ЧОН-ПОН",new ChonPonQuizPage(),new Size(1030,650));Register("АВТОВІДПОВІДІ",new AutoAnswerPage(),new Size(900,650));Register("SWAP PROBE",new SwapProbePage(),new Size(900,650));Register("РОЗМОРОЗКА",new UnfreezePage(),new Size(850,620));Register("СВІТОВІ БОСИ",new BossesPage(),new Size(930,660));ShowPage("ГОЛОВНА");UpdateTitleCount();progressTimer.Interval=1500;progressTimer.Tick+=(s,e)=>UpdateTitleCount();progressTimer.Start();Shown+=(s,e)=>CheckUpdates(false);}
