 async void CheckUpdates(bool manual){updateButton.Enabled=false;string old=updateButton.Text;updateButton.Text="ПЕРЕВІРКА...";try{UpdateInfo info=await UpdateService.CheckAsync(manual);if(info==null){if(manual)MessageBox.Show("У вас актуальна версія.","Оновлення",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}string notes=(info.Notes??"").Trim();if(notes.Length>1200)notes=notes.Substring(0,1200)+"...";var answer=MessageBox.Show("Доступна версія "+info.Tag+".\n\n"+notes+"\n\nЗавантажити та встановити?\nВаші титули, профілі й макроси буде збережено.","CyberPW Assistant — оновлення",MessageBoxButtons.YesNo,MessageBoxIcon.Information);if(answer!=DialogResult.Yes)return;updateButton.Text="ЗАВАНТАЖЕННЯ...";await UpdateService.DownloadAndStartAsync(info);Application.Exit();}catch(Exception e){if(manual)MessageBox.Show("Не вдалося перевірити оновлення.\n\n"+e.Message,"Оновлення",MessageBoxButtons.OK,MessageBoxIcon.Warning);}finally{updateButton.Enabled=true;updateButton.Text=old;}} void UpdateTitleCount(){try{int total=JsonFiles.Read<List<TitleRecord>>(AppPaths.Titles).Count,done=0;if(File.Exists(AppPaths.State)){var state=JsonFiles.Read<TitleState>(AppPaths.State);if(state!=null&&state.done!=null)done=state.done.Count(x=>x.Value);}titleCount.Text="Титули: "+done+" / "+total;}catch{titleCount.Text="Титули: — / 260";}}
 static string DisplayVersion(){try{string v=File.ReadAllText(Path.Combine(AppPaths.Root,"VERSION")).Trim();if(string.IsNullOrWhiteSpace(v))return "2.0 (BETA)";if(v.EndsWith("-beta",StringComparison.OrdinalIgnoreCase))return v.Substring(0,v.Length-5)+" (BETA)";return v;}catch{return "2.0 (BETA)";}}
 static void OpenLink(string url){try{Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}catch(Exception e){MessageBox.Show("Не вдалося відкрити посилання.\n"+e.Message,"CyberPW Assistant");}}
 Icon LoadIcon(){try{string p=Path.Combine(AppPaths.Root,"cyberpw-logo.ico");return File.Exists(p)?new Icon(p):null;}catch{return null;}}Image LoadLogo(){try{string p=Path.Combine(AppPaths.Root,"cyberpw-logo.png");if(!File.Exists(p))return null;using(var s=Image.FromFile(p))return new Bitmap(s);}catch{return null;}}
 void BuildNav(){var logo=new PictureBox{Image=LoadLogo(),SizeMode=PictureBoxSizeMode.Zoom,BackColor=Color.Transparent};logo.SetBounds(24,12,182,76);nav.Controls.Add(logo);var brand=Theme.Label("CyberPW Assistant",14,Theme.GoldSoft,FontStyle.Bold);brand.Location=new Point(24,94);nav.Controls.Add(brand);var ver=Theme.Label(DisplayVersion(),9,Theme.Cyan,FontStyle.Bold);ver.Location=new Point(25,124);nav.Controls.Add(ver);string[,] items={{"ГОЛОВНА","home.jpg"},{"TITULHELPER","titles.jpg"},{"MULTILAUNCHER","multilauncher.jpg"},{"МАКРОСИ","macros.jpg"},{"РЕСИ","titles.jpg"},{"СИМУЛЯТОР","simulator.jpg"},{"ЗАТОЧКА","simulator.jpg"},{"ВІКТОРИНА КХ","titles.jpg"},{"ВІКТОРИНА ЧОН-ПОН","titles.jpg"},{"АВТОВІДПОВІДІ","titles.jpg"},{"SWAP PROBE","simulator.jpg"},{"РОЗМОРОЗКА","unfreeze.jpg"},{"СВІТОВІ БОСИ","bosses.jpg"}};int y=170;for(int i=0;i<items.GetLength(0);i++){string key=items[i,0];string caption=(key=="РЕСИ"||key=="СИМУЛЯТОР"||key=="ЗАТОЧКА")?key+" · BETA":((key=="АВТОВІДПОВІДІ"||key=="SWAP PROBE")?key+" · SUPER BETA":key);var b=Theme.Button(caption);b.SetBounds(16,y,198,45);b.TextAlign=ContentAlignment.MiddleLeft;b.Image=AssetImages.LoadSized(30,30,"icons",items[i,1]);b.ImageAlign=ContentAlignment.MiddleLeft;b.TextImageRelation=TextImageRelation.ImageBeforeText;b.Padding=new Padding(10,0,4,0);b.Click+=(s,e)=>ShowPage(key);nav.Controls.Add(b);y+=51;}var support=Theme.Button("ПІДТРИМАТИ ПРОЄКТ");support.SetBounds(16,y+8,198,42);support.BackColor=Color.FromArgb(125,82,5);support.Click+=(s,e)=>OpenLink("https://send.monobank.ua/jar/93N5FBB3zX");nav.Controls.Add(support);var site=Theme.Button("САЙТ CYBERPW");site.SetBounds(16,y+58,198,38);site.ForeColor=Theme.Muted;site.Click+=(s,e)=>OpenLink("https://cyberpw.fun/");nav.Controls.Add(site);}
